cardCss:
.yijing-card {
    background: var(--card-bg, #fffdf8);
    border-radius: 16px;
    padding: 16px 20px;
    box-shadow: 0 1px 3px rgba(140,109,63,.10), 0 6px 16px rgba(140,109,63,.08);
    border: 1px solid var(--line, #ece3d2);
    border-left: 4px solid #b48a3f;
    min-height: 260px; display: flex; flex-direction: column;
    transition: transform .25s, box-shadow .25s;
    margin-bottom: 16px;
}
.yijing-card:hover { transform: translateY(-3px); box-shadow: 0 10px 26px rgba(140,109,63,.14); }
.yijing-card.highlighted { border-left-color: var(--unknown, #f43f5e); background: #fdf3ef; }
.yijing-card:active { transform: scale(.99); }

.yj-header { display: flex; align-items: center; justify-content: space-between; gap: 10px; margin-bottom: 10px; }
.yj-basic { display: flex; align-items: baseline; gap: 10px; flex-wrap: wrap; min-width: 0; }
.yj-index { color: #b48a3f; font-weight: var(--card-font-weight, 700); font-size: calc(13px * var(--card-font-scale, 1)); }
.yj-name { font-family: "Songti SC","STSong","SimSun",serif; font-weight: var(--card-font-weight, 800); color: #1f2937; font-size: calc(30px * var(--card-font-scale, 1)); letter-spacing: 4px; }
.yj-pinyin { color: #6b7280; font-size: calc(14px * var(--card-font-scale, 1)); }

.yj-tools { display: flex; gap: 6px; flex-shrink: 0; }
.yj-tools .action-btn { width: 40px; height: 40px; border: none; background: var(--action-btn-bg, #f3ede2); border-radius: 90px; cursor: pointer; display: flex; align-items: center; justify-content: center; color: #6b7280; transition: all .2s; }
.yj-tools .action-btn svg, .action-btn i { width: 22px; height: 22px; transition: transform .18s; }
.yj-tools .action-btn:hover { transform: translateY(-2px); }
.yj-tools .act-play:hover { background: #b48a3f; color: #fff; box-shadow: 0 4px 12px rgba(180,138,63,.3); }
.yj-tools .act-mark.is-active { color: var(--unknown, #f43f5e); }
.yj-tools .act-fav.is-active { color: #eab308; }

.yj-mid { display: flex; align-items: center; gap: 20px; margin-bottom: 10px; }
.yj-hex { flex-shrink: 0; }
.hex-lines { display: flex; flex-direction: column; gap: 6px; }
.hex-line { width: 66px; height: 9px; border-radius: 5px; background: #1f2937; }
.hex-line.yin { background: transparent; position: relative; }
.hex-line.yin::before, .hex-line.yin::after { content: ""; position: absolute; top: 0; height: 9px; width: 27px; background: #1f2937; border-radius: 5px; }
.hex-line.yin::before { left: 0; }
.hex-line.yin::after { right: 0; }

.yj-struct { min-width: 0; }
.yj-label { font-size: calc(12px * var(--card-font-scale, 1)); color: #9a7b4f; font-weight: var(--card-font-weight, 600); margin-bottom: 4px; letter-spacing: 1px; }
.yj-struct-text { font-family: "Songti SC","STSong","SimSun",serif; font-size: calc(18px * var(--card-font-scale, 1)); color: #374151; }

.yj-section { margin-top: 8px; }
.yj-judgment { font-family: "Songti SC","STSong","SimSun",serif; font-size: calc(16px * var(--card-font-scale, 1)); line-height: 1.6; color: #1f2937; }
.yj-meaning { font-size: calc(14px * var(--card-font-scale, 1)); line-height: 1.7; color: #4b5563; }
.yj-section.hide, .yj-mid.hide { display: none; }

.action-btn i { font-size: 18px; line-height: 1; }
.action-btn:hover i { transform: scale(1.1); }

cardJs:
(function () {
    'use strict';
    function esc(s) {
        if (s == null) return '';
        return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
    }
    window.cardTemplate = {
        name: '易经卦象卡',
        fields: [
            { key: 'number',    label: '卦序', hideable: false },
            { key: 'name',      label: '卦名', hideable: false },
            { key: 'pinyin',    label: '拼音' },
            { key: 'structure', label: '卦象' },
            { key: 'lines',     label: '卦画' },
            { key: 'judgment',  label: '卦辞' },
            { key: 'meaning',   label: '释义' }
        ],
        render: function (cardHtml, cardData, api) {
            var data = api.getCardData ? api.getCardData() : cardData;
            var d = data.data || {};
            var hidden = (api.getHiddenFields && api.getHiddenFields()) || {};
            function isHidden(k) { return hidden.has && hidden.has(k); }
            function wrap(k, html) { return isHidden(k) ? '' : html; }
            var markActive = data.is_unknown === 1 ? 'is-active' : '';
            var favActive = data.is_favorite === 1 ? 'is-active' : '';
            var lines = d.lines || '';
            var hexHtml = '';
            for (var i = 0; i < lines.length; i++) {
                var yin = lines.charAt(i) === '0';
                hexHtml += '<div class="hex-line ' + (yin ? 'yin' : 'yang') + '"></div>';
            }
            var order = String(data.current_order != null ? data.current_order : (d.number || '')).padStart(2, '0');
            return '<div class="yijing-card ' + (data.is_unknown === 1 ? 'highlighted' : '') + '" data-card-id="' + data.id + '">' +
                '<div class="yj-header">' +
                    '<div class="yj-basic">' +
                        wrap('number', '<span class="yj-index">' + order + '</span>') +
                        wrap('name', '<span class="yj-name">' + esc(d.name) + '</span>') +
                        wrap('pinyin', '<span class="yj-pinyin">' + esc(d.pinyin) + '</span>') +
                    '</div>' +
                    '<div class="yj-tools">' +
                        '<button class="action-btn act-play" data-action="play" data-tooltip="朗读卦名"><i class="fa-solid fa-volume-high"></i></button>' +
                        '<button class="action-btn act-mark ' + markActive + '" data-action="mark" data-tooltip="标记"><i class="' + (data.is_unknown === 1 ? 'fa-solid' : 'fa-regular') + ' fa-star"></i></button>' +
                        '<button class="action-btn act-fav ' + favActive + '" data-action="favorite" data-tooltip="收藏"><i class="' + (data.is_favorite === 1 ? 'fa-solid' : 'fa-regular') + ' fa-bookmark"></i></button>' +
                    '</div>' +
                '</div>' +
                '<div class="yj-mid">' +
                    wrap('lines', '<div class="yj-hex"><div class="hex-lines">' + hexHtml + '</div></div>') +
                    wrap('structure', '<div class="yj-struct"><div class="yj-label">卦象</div><div class="yj-struct-text">' + esc(d.structure) + '</div></div>') +
                '</div>' +
                wrap('judgment', '<div class="yj-section"><div class="yj-label">卦辞</div><div class="yj-judgment">' + esc(d.judgment) + '</div></div>') +
                wrap('meaning', '<div class="yj-section"><div class="yj-label">释义</div><div class="yj-meaning">' + esc(d.meaning) + '</div></div>') +
            '</div>';
        },
        init: function (cardElement, cardData, api) {
            api.track('definition_view');
            var playBtn = cardElement.querySelector('[data-action="play"]');
            if (playBtn) playBtn.addEventListener('click', function () {
                var d = cardData.data || {};
                api.playAudio(d.name || '');
                api.track('audio_play');
            });
            var markBtn = cardElement.querySelector('[data-action="mark"]');
            if (markBtn) markBtn.addEventListener('click', function () {
                api.toggleMark().then(function () { api.rerender(); });
                api.track('word_mark');
            });
            var favBtn = cardElement.querySelector('[data-action="favorite"]');
            if (favBtn) favBtn.addEventListener('click', function () {
                api.toggleFavorite().then(function () { api.rerender(); });
                api.track('favorite_toggle');
            });
        }
    };
})();
